"""chesspawn_exact: parametric CadQuery model generated by stl2cad (exact mode, revolve).

The part is one profile revolved 360 degrees about the y axis through (0.0, 0.0, 0.0). The profile is drawn
with u = distance from the axis and v = position along it. Units: mm.
Run:  python chesspawn_exact.py [out.step]
"""

import sys

from cadquery import Edge, Face, Solid, Vector, Wire

# ---- axis ----------------------------------------------------------------
AXIS_POINT = Vector(0.0, 0.0, 0.0)
AXIS_DIR = Vector(0.0, 1.0, 0.0)
RADIAL = Vector(1.0, 0.0, 0.0)          # the profile's u direction


def P(u, v):
    """Profile point: u from the axis, v along it."""
    return AXIS_POINT + RADIAL * u + AXIS_DIR * v


# ---- profile --------------------------------------------------------------
outline = Wire.assembleEdges([
    Edge.makeThreePointArc(P(0.0, 0.0), P(6.8465, -4.4381), P(5.5902, -12.5)),
    Edge.makeLine(P(5.5902, -12.5), P(6.5, -12.5)),
    Edge.makeThreePointArc(P(6.5, -12.5), P(8.0, -14.0), P(6.5, -15.5)),
    Edge.makeLine(P(6.5, -15.5), P(4.0027, -15.5)),
    Edge.makeThreePointArc(P(4.0027, -15.5), P(4.5758, -20.7099), P(7.564, -26.2319)),
    Edge.makeThreePointArc(P(7.564, -26.2319), P(8.9569, -30.848), P(6.5047, -35.0)),
    Edge.makeLine(P(6.5047, -35.0), P(9.0, -35.0)),
    Edge.makeThreePointArc(P(9.0, -35.0), P(10.5, -36.5), P(9.0, -38.0)),
    Edge.makeLine(P(9.0, -38.0), P(0.0, -38.0)),
    Edge.makeLine(P(0.0, -38.0), P(0.0, 0.0)),
])

profile = Face.makeFromWires(outline, [])
part = Solid.revolve(profile, 360.0, AXIS_POINT, AXIS_POINT + AXIS_DIR)

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "chesspawn_exact.step")
